/*
 * A243958  Primes of the form 2*n^2+86*n+41.
 * https://oeis.org/A243958
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the n‑th prime of the quadratic 2*k^2+86*k+41 (k ≥ 1).
 *            The sequence is generated by checking f(k)=2*k*k+86*k+41 for
 *            primality and collecting the primes
 * Range:     u8 none, u16 n <= 46, u32 n <= 86, u64 n <= 1000, u128 n <= 1000,
 *            big any n
 * Helpers:   grow_seq, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include "../utils/is_prime_big.h"
#include "../utils/grow_seq.h"

static seq_t *primes = NULL;      /* stored primes */
static size_t primes_cap = 0;     /* capacity of primes array   */
static size_t primes_len = 0;     /* number of primes found    */
static idx_t next_k = 1;          /* next k to test             */

seq_t a(idx_t n) {
    if (n == 0) return 0;            /* undefined for n < 1 */
    while (primes_len < n) {         /* generate until we have n primes */
        idx_t k = next_k++;
        /* compute f(k) = 2*k^2 + 86*k + 41 */
        seq_t val = (seq_t)2 * ((seq_t)k * (seq_t)k)
                    + (seq_t)86 * (seq_t)k
                    + (seq_t)41;
        if (is_prime_big(val)) {
            grow_seq(&primes, &primes_cap, primes_len + 1);
            primes[primes_len++] = val;
        }
    }
    return primes[n - 1];
}
